<?php require 'bootstrap.php';require_login();if(me()['role']!=='superadmin')exit('Acceso denegado');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(in_array($_POST['status']??'', ['approved','rejected','suspended'],true)){$s=$db->prepare('UPDATE churches SET status=? WHERE id=?');$s->execute([$_POST['status'],(int)$_POST['id']]);audit($db,'church_status','church',(int)$_POST['id']);}header('Location: approvals.php');exit;}require 'layout.php';top('Solicitudes');echo '<h1>Administrar iglesias</h1><section class="card"><table><tr><th>Iglesia</th><th>Correo</th><th>Estado</th><th>Acción</th></tr>';foreach($db->query('SELECT * FROM churches ORDER BY created_at DESC') as $c){echo '<tr><td>'.e($c['name']).'</td><td>'.e($c['email']).'</td><td>'.e($c['status']).'</td><td><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="id" value="'.(int)$c['id'].'"><select name="status"><option value="approved">Aprobar</option><option value="rejected">Rechazar</option><option value="suspended">Suspender</option></select><button>Aplicar</button></form></td></tr>';}echo '</table></section>';bottom();
